package com.gamehub.application.service; import com.gamehub.application.OperationsService; import java.time.Instant; import java.util.List; public final class TournamentService { private final OperationsService ops; public TournamentService(OperationsService ops){this.ops=ops;} public List<String> tournaments()throws Exception{return ops.tournaments();} public long create(long a,String n,String f,String e,int cap,long fee)throws Exception{return ops.createTournament(a,n,f,e,cap,fee);} public void configure(long a,long t,String g,Instant o,Instant c,Instant s,String el)throws Exception{ops.configureTournament(a,t,g,o,c,s,el);} public void transition(long a,long t,String st)throws Exception{ops.changeTournamentStatus(a,t,st);} }